#include <iostream>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string S, T;
    std::getline(std::cin, S);
    std::getline(std::cin, T);

    std::string ans = "YES";
    size_t j = 0;
    if (S.length() != T.length()) {
        ans = "NO";
    } else {
        for (int i = static_cast<int>(T.length()) - 1; i >= 0; --i) {
            if (T[i] != S[j]) {
                ans = "NO";
                break;
            }
            ++j;
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

